function discoveryPool(items,limit){const src=Array.isArray(items)?items:[],cap=Math.max(30,Math.round(n(limit)||120));const metrics=['volumeAmount','tradeVolume','volume'];const rankMaps=new Map();for(const key of metrics){[...src].sort((a,b)=>(n(b?.[key])||0)-(n(a?.[key])||0)).forEach((x,i)=>{const sym=String(x.symbol||'').toUpperCase();if(!sym)return;const cur=rankMaps.get(sym)||{row:x,best:Infinity};cur.best=Math.min(cur.best,i);rankMaps.set(sym,cur)})}return [...rankMaps.values()].filter(x=>x.best<cap).sort((a,b)=>a.best-b.best||(n(b.row?.volumeAmount)||0)-(n(a.row?.volumeAmount)||0)).slice(0,Math.min(src.length,cap*2)).map(x=>x.row)}
