function progressPct(){const p=progressState,t=Math.max(0,p.total||0);let v=0;if(p.sourcesDone)v+=PROGRESS_WEIGHTS.sources;if(p.universeDone)v+=PROGRESS_WEIGHTS.universe;if(p.liquidityDone)v+=PROGRESS_WEIGHTS.liquidity;if(t>0){v+=PROGRESS_WEIGHTS.daily*Math.min(1,p.dailyDone/t);v+=PROGRESS_WEIGHTS.weekly*Math.min(1,p.weeklyDone/t);v+=PROGRESS_WEIGHTS.fundamental*Math.min(1,p.fundamentalDone/t)}if(p.positionsDone)v+=PROGRESS_WEIGHTS.positions;if(!p.active&&!p.error&&p.positionsDone)v=100;return Math.max(0,Math.min(100,Math.round(v)))}
