async function recordSale(idx){const p=model.positions[idx];if(!p)return;const pctRaw=await window.radarPrompt(`Porcentaje de ${p.symbol} efectivamente vendido`,p.state?.key==='REALIZE'?'100':'25',{title:'Registrar venta',inputLabel:'Porcentaje vendido',inputMode:'decimal',confirmLabel:'Continuar'});if(pctRaw===null)return;const soldPct=n(pctRaw);if(!(soldPct>0&&soldPct<=100)){window.radarNotify('El porcentaje debe estar entre 0 y 100.','warn');return}const estimate=n(p.valuation?.usdRealizable)>0?n(p.valuation.usdRealizable)*soldPct/100:NaN;const actualRaw=await window.radarPrompt(`USD netos efectivamente recuperados. Dejá vacío si todavía no ejecutaste la venta.${Number.isFinite(estimate)?` Estimación Radar: ${estimate.toFixed(2)} USD.`:''}`,'',{title:'Confirmar materialización',inputLabel:'USD netos recuperados',inputMode:'decimal',confirmLabel:'Registrar'});if(actualRaw===null)return;const actual=actualRaw.trim()===''?NaN:n(actualRaw);const investedPart=(n(p.valuation?.usdInvested)||n(p.usdInvested))*soldPct/100;if(!Number.isFinite(actual)){event('REALIZE',p.symbol,`Decisión de materializar ${soldPct.toFixed(1)}% registrada; venta aún no confirmada`,{usdValue:estimate,rotationScore:p.rotation?.score,metadata:{confirmed:false,soldPct,estimatedUsd:estimate}});save();renderHistory();return}if(!(actual>=0)){window.radarNotify('USD recuperados inválidos.','warn');return}const realizedPnlUsd=Number.isFinite(investedPart)?actual-investedPart:NaN;event('REALIZE',p.symbol,`Materialización confirmada ${soldPct.toFixed(1)}%`,{usdValue:actual,rotationScore:p.rotation?.score,metadata:{confirmed:true,soldPct,realizedPnlUsd,investedUsd:investedPart}});const remain=1-soldPct/100;p.quantity=n(p.quantity)*remain;if(Number.isFinite(n(p.usdInvested)))p.usdInvested=n(p.usdInvested)*remain;if(p.quantity<=1e-10)model.positions.splice(idx,1);save();renderAll();refreshAll()}
function historyMetrics(){const realized=model.history.filter(e=>e.type==='REALIZE'&&e.metadata?.confirmed&&Number.isFinite(n(e.metadata?.realizedPnlUsd))),wins=realized.filter(e=>n(e.metadata.realizedPnlUsd)>0),losses=realized.filter(e=>n(e.metadata.realizedPnlUsd)<0),gp=sumFinite(wins.map(e=>n(e.metadata.realizedPnlUsd))),gl=Math.abs(sumFinite(losses.map(e=>n(e.metadata.realizedPnlUsd)))),pf=gl>0?gp/gl:(gp>0?Infinity:NaN),exp=realized.length?sumFinite(realized.map(e=>n(e.metadata.realizedPnlUsd)))/realized.length:NaN;return{decisions:model.history.length,realized:realized.length,hitRate:realized.length?wins.length/realized.length*100:NaN,profitFactor:pf,expectancy:exp,realizedUsd:sumFinite(realized.map(e=>n(e.usdValue))),rotations:model.history.filter(e=>e.type==='ROTATE').length}}
